def mean(xs):return statistics.fmean(xs)
def main():
 cfg=load(ROOT/'configs/posttraining/train-m3-full-ft-v1.json');cv=load(RUN/'cv-summary.json');dev=load(RUN/'dev-summary.json');final=load(ROOT/'configs/posttraining/m3-finalist-v1.json');bench=load(Path.home()/'rag/runs/posttraining/benchmark-eval-m3-v1/final-results.json');m2=load(ROOT/'docs/posttraining/milestone4-m2-lora-mixed-results.json')
 selected=str(final['selected_epochs']);sel=dev['results'][selected];m2dev=m2['dev_finalists']['3']['mean_sample_sd'];cvtrain=[load(RUN/f'cv/fold-{i}/metrics.json') for i in range(5)];finaltrain=[load(RUN/f'dev-finalists/seed-{s}/metrics.json') for s in range(3)];alltrain=cvtrain+finaltrain
 compute={'cv_training_seconds':sum(x['training_seconds'] for x in cvtrain),'cv_gpu_hours':sum(x['gpu_hours'] for x in cvtrain),'final_training_seconds':sum(x['training_seconds'] for x in finaltrain),'final_gpu_hours':sum(x['gpu_hours'] for x in finaltrain),'total_training_seconds':sum(x['training_seconds'] for x in alltrain),'total_gpu_hours':sum(x['gpu_hours'] for x in alltrain),'peak_memory_mib':max(max(x['peak_memory_mib_per_gpu']) for x in alltrain),'mean_final_tokens_per_second':mean(x['tokens_per_second'] for x in finaltrain)}
 payload={'status':'complete','milestone':'M3_full_parameter_fine_tuning','implementation_validated':True,'configuration':cfg,'trainable_parameters':3085938688,'cv':cv,'selected_epoch':int(selected),'dev':dev['results'],'selected_dev_minus_M2':{'accuracy':sel['mean_sample_sd']['accuracy']['mean']-m2dev['accuracy']['mean'],'macro_f1':sel['mean_sample_sd']['macro_f1']['mean']-m2dev['macro_f1']['mean'],'support_recall':sel['mean_sample_sd']['support_recall']['mean']-m2dev['support_recall']['mean'],'contradict_recall':sel['mean_sample_sd']['contradict_recall']['mean']-m2dev['contradict_recall']['mean'],'insufficient_recall':sel['mean_sample_sd']['insufficient_recall']['mean']-m2dev['insufficient_recall']['mean']},'benchmark':bench,'compute':compute,'checkpoint':final['inferential_checkpoint'],'checkpoint_weights':final['inferential_weight_sha256'],'limitations':['DistributedSampler pads the 573-row dataset to 576 samples per epoch across four ranks; no new source rows are introduced.','The benchmark was previously evaluated in v1 and is not a pristine unseen test set.','M3 is a secondary comparison and test 6 remains outside the original Holm family.']}
 out=ROOT/'docs/posttraining/milestone5-m3-full-ft-results.json';out.write_text(json.dumps(payload,indent=2)+'\n')
 lines=['# Milestone 5 — M3 full-parameter fine-tuning','', 'M3 asks whether full-parameter Qwen2.5-3B-Instruct fine-tuning improves enough over the frozen M2 LoRA system to justify its compute and systems cost. It uses the identical frozen Mix-2 data and no benchmark examples for training or selection.','', '## Frozen configuration','',f"- Mix-2: 573 rows (A 344 / B 86 / C 86 / D 57), SHA-256 `{cfg['training_data']['sha256']}`",f"- Model/tokenizer revision: `{cfg['model_revision']}`",f"- Trainable parameters: **3,085,938,688**; no LoRA",'- AdamW, LR 1e-5, weight decay 0.01, linear schedule, 10% warmup, BF16 compute with FP32 masters, maximum length 4,096, output-only loss','- FSDP FULL_SHARD on four L40S GPUs, microbatch 2/GPU, accumulation 2, global batch 16, no CPU offload','', '## Grouped cross-validation','', '| Epoch | Fold macro F1 | Mean macro F1 | Mean accuracy |','|---:|---|---:|---:|']
 for e in ('2','3'):
  x=cv['candidates'][e];lines.append(f"| {e} | "+', '.join(f'{v:.4f}' for v in x['fold_macro_f1'])+f" | {x['mean_macro_f1']:.4f} | {x['mean_accuracy']:.4f} |")
 lines += ['', 'Both predeclared finalists advanced to the frozen three-seed DEV comparison.','', '## Frozen DEV results','', '| Epoch | Seed | Accuracy | Macro F1 | SUPPORT recall | CONTRADICT recall | INSUFFICIENT recall | JSON valid | Decision valid | Rationale-index valid |','|---:|---:|---:|---:|---:|---:|---:|---:|---:|---:|']
 for e in ('2','3'):
  for x in dev['results'][e]['seeds']:
   lines.append(f"| {e} | {x['seed']} | {x['accuracy']:.4f} | {x['macro_f1']:.4f} | {x['per_label']['SUPPORT']['recall']:.4f} | {x['per_label']['CONTRADICT']['recall']:.4f} | {x['per_label']['INSUFFICIENT']['recall']:.4f} | {x['json_valid_rate']:.4f} | {x['decision_valid_rate']:.4f} | {x['rationale_index_valid_rate']:.4f} |")
 lines += ['', '| Epoch | Mean ± SD accuracy | Mean ± SD macro F1 |','|---:|---:|---:|']
 for e in ('2','3'):
  a=dev['results'][e]['mean_sample_sd']['accuracy'];f=dev['results'][e]['mean_sample_sd']['macro_f1'];lines.append(f"| {e} | {a['mean']:.4f} ± {a['sample_sd']:.4f} | {f['mean']:.4f} ± {f['sample_sd']:.4f} |")
 lines += ['',f"The frozen rule selected **epoch {selected}**. Seed 0 is the predeclared inferential checkpoint: `{final['inferential_checkpoint']}`.",'', '## Fixed benchmark and M3 versus M2','']
 b=bench['M3'];c=bench['test6_M3_vs_M2'];lines += [f"M3 reached **{b['accuracy']:.4f} accuracy** and **{b['macro_f1']:.4f} macro F1** on the fixed 300-claim SciFact benchmark split, previously evaluated in v1 and not used for M3 training or model selection.",'',f"Relative to the saved M2 predictions, accuracy changed by **{c['accuracy_difference']:+.4f}** and macro F1 by **{c['macro_f1_difference']:+.4f}** (paired bootstrap 95% CI [{c['macro_f1_bootstrap_95_ci'][0]:.4f}, {c['macro_f1_bootstrap_95_ci'][1]:.4f}]). Exact paired McNemar p = **{c['mcnemar_exact_raw_p']:.4g}**; test 6 is separate from the original Holm family.",'',f"Calibration: ECE {b['calibration']['ece']:.4f}, Brier {b['calibration']['brier_score']:.4f}, NLL {b['calibration']['nll']:.4f}, restricted-choice/generation agreement {b['calibration']['restricted_generation_agreement_rate']:.4f}. Rationale precision/recall/F1: {b['rationale']['precision']:.4f}/{b['rationale']['recall']:.4f}/{b['rationale']['f1']:.4f} over {b['rationale']['eligible_count']} eligible examples.",'', '## Compute and interpretation','',f"Cross-validation plus final training took {compute['total_training_seconds']/3600:.2f} aggregate wall-clock hours and **{compute['total_gpu_hours']:.2f} GPU-hours**. Peak PyTorch allocation was **{compute['peak_memory_mib']:.0f} MiB/GPU**; final-run mean throughput was **{compute['mean_final_tokens_per_second']:.1f} tokens/s**.",'',f"On DEV, selected M3 minus M2 was {payload['selected_dev_minus_M2']['accuracy']:+.4f} accuracy and {payload['selected_dev_minus_M2']['macro_f1']:+.4f} macro F1. The benchmark comparison determines whether this translated into a reliable practical gain. Full fine-tuning is justified only if that quality evidence outweighs the substantially higher memory, GPU-hour, storage, and distributed-systems cost.",'','A four-rank distributed sampler pads 573 rows to 576 samples per epoch, repeating three existing rows; it introduces no new source examples. The fixed benchmark is not described as pristine unseen data. No serving integration was performed.','']
 (ROOT/'docs/posttraining/milestone5-m3-full-ft.md').write_text('\n'.join(lines))
 print(json.dumps({'selected_epoch':int(selected),'dev_macro_f1':sel['mean_sample_sd']['macro_f1'],'benchmark_accuracy':b['accuracy'],'benchmark_macro_f1':b['macro_f1'],'test6':c,'compute':compute},indent=2))
